diff --git a/user_handler.go b/user_handler.go
new file mode 100644
--- /dev/null
+++ b/user_handler.go
@@ -0,0 +1,6 @@
+func getUser(db *sql.DB, name string) (*User, error) {
+	row := db.QueryRow("SELECT id, name FROM users WHERE name = ?", name)
+	var u User
+	if err := row.Scan(&u.ID, &u.Name); err != nil {
+		return nil, err
+	}
+	return &u, nil
+}
